// Private file storage (uploaded statements and supporting documents).
// Production: a private Supabase Storage bucket accessed only from the server
// with the service-role key. Tests: an in-memory store.
//
// Object keys are generated by the server as "<firm id>/<case id>/<document id>.<ext>";
// callers never choose a path, and every key is checked before use.

import { createClient, type SupabaseClient } from "@supabase/supabase-js";
import { getConfig } from "./config";

const KEY = /^([0-9a-f-]{36})\/([0-9a-f-]{36})\/([0-9a-f-]{36})\.([a-z0-9]{1,8})$/;

export class StorageError extends Error {
  constructor(readonly code: "invalid_key" | "not_found" | "already_exists" | "storage_failed") {
    super(code);
    this.name = "StorageError";
  }
}

export function storageKey(firmId: string, caseId: string, documentId: string, extension: string): string {
  const key = `${firmId}/${caseId}/${documentId}.${extension}`;
  checkKey(key);
  return key;
}

export function checkKey(key: string): void {
  if (!KEY.test(key)) throw new StorageError("invalid_key");
}

export interface FileStore {
  /** Store new bytes; never overwrites an existing object. */
  put(key: string, data: Uint8Array, contentType: string): Promise<void>;
  get(key: string): Promise<Uint8Array>;
  remove(key: string): Promise<void>;
}

class SupabaseStore implements FileStore {
  constructor(
    private readonly client: SupabaseClient,
    private readonly bucket: string,
  ) {}

  async put(key: string, data: Uint8Array, contentType: string) {
    checkKey(key);
    const { error } = await this.client.storage.from(this.bucket).upload(key, data, { contentType, upsert: false });
    if (error) {
      throw new StorageError(/exist|duplicate/i.test(error.message) ? "already_exists" : "storage_failed");
    }
  }

  async get(key: string) {
    checkKey(key);
    const { data, error } = await this.client.storage.from(this.bucket).download(key);
    if (error || !data) throw new StorageError(/not.?found/i.test(error?.message ?? "") ? "not_found" : "storage_failed");
    return new Uint8Array(await data.arrayBuffer());
  }

  async remove(key: string) {
    checkKey(key);
    const { error } = await this.client.storage.from(this.bucket).remove([key]);
    if (error) throw new StorageError("storage_failed");
  }
}

export class MemoryStore implements FileStore {
  readonly objects = new Map<string, { data: Uint8Array; contentType: string }>();

  async put(key: string, data: Uint8Array, contentType: string) {
    checkKey(key);
    if (this.objects.has(key)) throw new StorageError("already_exists");
    this.objects.set(key, { data: new Uint8Array(data), contentType });
  }

  async get(key: string) {
    checkKey(key);
    const found = this.objects.get(key);
    if (!found) throw new StorageError("not_found");
    return new Uint8Array(found.data);
  }

  async remove(key: string) {
    checkKey(key);
    this.objects.delete(key);
  }
}

let shared: FileStore | null = null;

export function getFileStore(): FileStore {
  if (!shared) {
    const config = getConfig();
    if (!config.supabaseUrl || !config.supabaseServiceRoleKey) {
      throw new Error("File storage needs SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY");
    }
    const client = createClient(config.supabaseUrl, config.supabaseServiceRoleKey, {
      auth: { persistSession: false, autoRefreshToken: false },
    });
    shared = new SupabaseStore(client, config.storageBucket);
  }
  return shared;
}

export function setFileStoreForTests(store: FileStore | null): void {
  shared = store;
}
